//! Phase 1A: branded HTML/plain-text email templates for every event defined
//! in `docs/mail/AFYAMKONONI_EMAIL_CONTENT_V1.md` (the approved-copy source
//! of truth) and `docs/mail/AFYAMKONONI_EMAIL_DESIGN_BRIEF.md` (the visual/
//! structural specification). **Not wired to any trigger anywhere in this
//! codebase** — no `admin_handlers.rs`/`notification_service.rs`/
//! `email_delivery.rs` call site renders or sends any of these yet. See
//! `docs/mail/previews/` for browser-inspectable output generated by this
//! exact module (`examples/generate_email_previews.rs`), and that
//! directory's own notes for a list of open design items.
//!
//! ## Content fidelity
//! Every template's approved sentences are reproduced verbatim from the
//! content document; only the five HTML-meaningful characters in
//! interpolated *variables* are escaped (`html_escape`). The content
//! document's footer wording is inconsistent between templates (some omit
//! the "AfyaMkononi" brand line; contact-line labels vary: "Need help?",
//! "Questions?", "Professional support:", "Payment support:", "Security
//! assistance:", "Need assistance?"). The design brief's master structure
//! (section 5) mandates the full branded footer on every email, so this
//! module applies that structure uniformly to all eleven templates while
//! using each template's own approved contact-line label verbatim — no
//! footer wording was invented, only its layout was made consistent, per
//! the design brief's own acceptance criterion 7 ("GHI and RMCL appear
//! consistently in the footer").
//!
//! ## Links
//! Per product direction, every call-to-action button in these templates
//! leads back into the originating app/portal (not to a per-record deep
//! link) — `EmailLinks` carries exactly two URLs (`patient_app_url`,
//! `doctor_portal_url`), reused across every template for the relevant
//! audience. Both are validated (`validate_https_url`) before being
//! rendered; an invalid or absent URL causes the button to be omitted
//! entirely rather than rendering a broken or unsafe link. Neither URL
//! exists in approved production configuration yet — see
//! `docs/mail/previews/README.md` for the placeholder values used here and
//! what needs confirming before activation.
//!
//! ## Illustrations
//! The design brief explicitly asks not to invent an official logo, so the
//! header uses a plain text wordmark, never an image. Hero illustrations
//! are simple, abstract, geometric SVG placeholders in the brand palette —
//! **not** the commissioned "diverse Kenyan and East African young adults"
//! editorial illustrations the brief calls for, which require real
//! artwork. `EmailAssets::none()` renders no hero image at all (the
//! production-safe default until real, hosted artwork is approved); when a
//! `base_url` is configured, hero images are emitted as `<img>` with
//! descriptive `alt` text. No template's essential information ever
//! depends on an image rendering — confirmed by this module's own
//! `image_disabled_readability` tests, which strip every `<img>` tag from
//! the rendered HTML and assert the key content is still present.

use std::fmt::Write as _;

/// Minimal, dependency-free HTML escaping for the five characters that
/// matter for breaking out of a text node or a double-quoted attribute:
/// `&`, `<`, `>`, `"`, `'`. Sufficient because every call site below only
/// ever interpolates escaped values into plain text nodes or
/// double-quoted attributes it fully controls — never into a script/style
/// context or an unquoted attribute.
pub fn html_escape(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for ch in input.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            other => out.push(other),
        }
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RenderedEmail {
    pub subject: String,
    pub html_body: String,
    pub text_body: String,
}

impl RenderedEmail {
    /// The concrete integration point with the Phase 0 backend transport:
    /// converts a rendered template directly into the exact message shape
    /// `services::email_transport::EmailTransport::send_email` consumes, so
    /// these templates are structurally wired to the real outbox/transport
    /// pipeline rather than a disconnected set of functions — see
    /// `tests::a_rendered_template_is_directly_consumable_by_the_backend_transport`
    /// for a full round-trip proof against the real trait. Still not wired
    /// to any trigger: nothing outside that test calls this yet.
    pub fn as_email_message<'a>(
        &'a self,
        recipient: &'a str,
    ) -> crate::services::email_transport::EmailMessage<'a> {
        crate::services::email_transport::EmailMessage {
            recipient,
            subject: &self.subject,
            plain_text_body: &self.text_body,
            html_body: Some(&self.html_body),
        }
    }
}

/// Where hero illustration files live, if anywhere. `base_url` is prefixed
/// (with a `/`) onto a per-template filename, e.g. `{base_url}/hero-welcome.svg`.
/// `EmailAssets::none()` — the default — renders no `<img>` tag at all, which
/// is always safe: these illustrations are purely decorative, so omitting
/// them never loses information (see the module doc's image-disabled note).
#[derive(Debug, Clone, Default)]
pub struct EmailAssets {
    base_url: Option<String>,
}

impl EmailAssets {
    pub fn none() -> Self {
        Self { base_url: None }
    }

    /// `base_url` is used as-is (no validation beyond non-empty) since it is
    /// operator-supplied server configuration, never end-user input.
    pub fn with_base_url(base_url: impl Into<String>) -> Self {
        let base_url = base_url.into();
        Self {
            base_url: (!base_url.trim().is_empty()).then_some(base_url),
        }
    }

    fn image_tag(&self, file: &str, alt: &str) -> String {
        match &self.base_url {
            Some(base) => format!(
                "<img src=\"{}/{file}\" alt=\"{}\" width=\"536\" style=\"display:block;width:100%;max-width:536px;height:auto;border:0;outline:none;text-decoration:none;\" />",
                base.trim_end_matches('/'),
                html_escape(alt),
            ),
            None => String::new(),
        }
    }
}

/// The two destinations every call-to-action button in these templates can
/// point to — see the module doc's "Links" section for why there is no
/// per-record deep link. Both are validated before rendering.
#[derive(Debug, Clone, Default)]
pub struct EmailLinks {
    patient_app_url: Option<String>,
    doctor_portal_url: Option<String>,
}

impl EmailLinks {
    pub fn none() -> Self {
        Self {
            patient_app_url: None,
            doctor_portal_url: None,
        }
    }

    pub fn new(patient_app_url: Option<&str>, doctor_portal_url: Option<&str>) -> Self {
        Self {
            patient_app_url: patient_app_url.and_then(validate_https_url),
            doctor_portal_url: doctor_portal_url.and_then(validate_https_url),
        }
    }

    fn patient(&self) -> Option<&str> {
        self.patient_app_url.as_deref()
    }

    fn doctor(&self) -> Option<&str> {
        self.doctor_portal_url.as_deref()
    }
}

/// Only an absolute `https://` URL with a real host, no embedded
/// credentials and no custom port is accepted — mirrors the same validation
/// shape already used for operator-supplied URLs elsewhere in this crate
/// (e.g. `AcsEmailTransport::from_config`'s endpoint check). Returns
/// `Some(url)` unchanged (never rewritten) on success.
fn validate_https_url(url: &str) -> Option<String> {
    let parsed = url.parse::<reqwest::Url>().ok()?;
    if parsed.scheme() != "https"
        || !parsed.username().is_empty()
        || parsed.password().is_some()
        || parsed.port().is_some()
        || parsed.host_str().is_none_or(str::is_empty)
    {
        return None;
    }
    Some(url.to_string())
}

fn fallback_name(name: &str) -> &str {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        "there"
    } else {
        trimmed
    }
}

fn fallback_doctor_name(name: &str) -> &str {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        "Colleague"
    } else {
        trimmed
    }
}

/// Brand palette (design brief §4). Kept as named constants rather than
/// inlined hex literals so every template draws from one reviewed set.
mod palette {
    pub const DEEP_TEAL: &str = "#164E59";
    pub const VIBRANT_TEAL: &str = "#087F8C";
    pub const MINT: &str = "#DDF5EE";
    pub const WARM_IVORY: &str = "#FAFAF6";
    pub const LAVENDER: &str = "#EAE7FA";
    pub const CHARCOAL: &str = "#24343B";
}

/// One CTA button, already validated — `href` is never user input (see
/// `EmailLinks`), so no further escaping of the URL is needed; the visible
/// label still goes through `html_escape` defensively even though every
/// current call site passes a static string literal.
#[derive(Clone, Copy)]
struct Cta<'a> {
    label: &'a str,
    href: &'a str,
}

fn cta_button_html(cta: Option<Cta<'_>>) -> String {
    match cta {
        None => String::new(),
        Some(Cta { label, href }) => format!(
            "<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px auto 0;\"><tr><td style=\"border-radius:9999px;background-color:{teal};\"><a href=\"{href}\" style=\"display:inline-block;padding:14px 32px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:{ivory};text-decoration:none;border-radius:9999px;\">{label}</a></td></tr></table>",
            teal = palette::VIBRANT_TEAL,
            ivory = palette::WARM_IVORY,
            href = href,
            label = html_escape(label),
        ),
    }
}

fn cta_text(cta: Option<Cta<'_>>) -> String {
    match cta {
        None => String::new(),
        Some(Cta { label, href }) => format!("\n{label}: {href}\n"),
    }
}

/// A two-column detail card used by every transactional (appointment /
/// payment / refund) template — the design brief's "date/time card"
/// treatment generalized to any label/value list. Every value is escaped.
fn detail_card_html(rows: &[(&str, &str)]) -> String {
    let mut out = String::from(
        "<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:20px 0;border-collapse:collapse;\">",
    );
    for (label, value) in rows {
        let _ = write!(
            out,
            "<tr><td style=\"padding:10px 14px;background-color:{mint};border-bottom:1px solid #FFFFFF;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:{teal};width:45%;\">{label}</td><td style=\"padding:10px 14px;background-color:{mint};border-bottom:1px solid #FFFFFF;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:bold;color:{charcoal};\">{value}</td></tr>",
            mint = palette::MINT,
            teal = palette::DEEP_TEAL,
            charcoal = palette::CHARCOAL,
            label = html_escape(label),
            value = html_escape(value),
        );
    }
    out.push_str("</table>");
    out
}

fn detail_card_text(rows: &[(&str, &str)]) -> String {
    rows.iter()
        .map(|(label, value)| format!("{label}: {value}"))
        .collect::<Vec<_>>()
        .join("\n")
}

/// Footer spec for one template — structure is uniform (see module doc);
/// only `contact_label` and `transactional_disclaimer` vary, both taken
/// directly from the approved content document.
struct Footer<'a> {
    contact_label: &'a str,
    transactional_disclaimer: bool,
}

fn footer_html(footer: &Footer<'_>) -> String {
    let disclaimer = if footer.transactional_disclaimer {
        "<div style=\"margin-top:10px;font-style:italic;color:#5B6B72;\">This is an automated transactional email. Please do not reply directly.</div>"
    } else {
        ""
    };
    format!(
        "<tr><td style=\"background-color:{lavender};padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:12px;color:{teal};\">\
<div style=\"font-weight:bold;font-size:14px;\">AfyaMkononi</div>\
<div style=\"margin:4px 0 10px;\">Your Health. Your Space. Your Way.</div>\
<div style=\"line-height:1.6;\">Operated by Global Health Initiatives (GHI)<br />Technology Partner: Research and Management Consultants Ltd. (RMCL)</div>\
<div style=\"margin-top:10px;\">{label} <a href=\"mailto:support@hellodoctor.asia\" style=\"color:{vibrant};text-decoration:underline;\">support@hellodoctor.asia</a></div>\
{disclaimer}\
</td></tr>",
        lavender = palette::LAVENDER,
        teal = palette::DEEP_TEAL,
        vibrant = palette::VIBRANT_TEAL,
        label = html_escape(footer.contact_label),
    )
}

fn footer_text(footer: &Footer<'_>) -> String {
    let mut out = format!(
        "--\nAfyaMkononi\nYour Health. Your Space. Your Way.\n\nOperated by Global Health Initiatives (GHI)\nTechnology Partner: Research and Management Consultants Ltd. (RMCL)\n\n{} support@hellodoctor.asia",
        footer.contact_label
    );
    if footer.transactional_disclaimer {
        out.push_str("\n\nThis is an automated transactional email. Please do not reply directly.");
    }
    out
}

/// Assembles one full HTML document: text wordmark header (never an image —
/// see module doc), optional hero illustration, the template's own body,
/// and the shared footer. Table-based, inline-styled, no external
/// stylesheet, no JavaScript, no tracking pixel — the standard email-safe
/// construction. The embedded `<style>` block is a progressive enhancement
/// only (a client that strips `<style>` still gets a correctly laid out,
/// fluid single-column email from the table structure alone).
#[allow(clippy::too_many_arguments)]
fn layout(
    subject: &str,
    preheader: &str,
    hero_file: Option<&str>,
    hero_alt: &str,
    assets: &EmailAssets,
    body_html: &str,
    footer: &Footer<'_>,
) -> String {
    let hero_html = hero_file
        .map(|file| assets.image_tag(file, hero_alt))
        .filter(|tag| !tag.is_empty())
        .map(|tag| {
            format!(
                "<tr><td style=\"background-color:{mint};padding:0;text-align:center;\">{tag}</td></tr>",
                mint = palette::MINT
            )
        })
        .unwrap_or_default();
    format!(
        "<!doctype html>\
<html lang=\"en\">\
<head>\
<meta charset=\"utf-8\" />\
<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\
<meta name=\"color-scheme\" content=\"light\" />\
<title>{subject_escaped}</title>\
<style>\
@media only screen and (max-width:600px) {{\
  .amk-container {{ width:100% !important; }}\
  .amk-padded {{ padding-left:20px !important; padding-right:20px !important; }}\
}}\
</style>\
</head>\
<body style=\"margin:0;padding:0;background-color:{ivory};\">\
<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;font-size:1px;line-height:1px;color:{ivory};\">{preheader_escaped}</div>\
<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:{ivory};\">\
<tr><td align=\"center\" style=\"padding:24px 12px;\">\
<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" class=\"amk-container\" style=\"max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;\">\
<tr><td style=\"background-color:{teal};padding:24px 32px;text-align:center;\">\
<div style=\"color:{ivory};font-family:Arial,Helvetica,sans-serif;font-size:20px;font-weight:bold;letter-spacing:0.5px;\">AfyaMkononi</div>\
<div style=\"color:{mint};font-family:Arial,Helvetica,sans-serif;font-size:12px;margin-top:4px;\">Your Health. Your Space. Your Way.</div>\
</td></tr>\
{hero_html}\
<tr><td class=\"amk-padded\" style=\"padding:32px;font-family:Arial,Helvetica,sans-serif;color:{charcoal};font-size:15px;line-height:1.6;\">\
{body_html}\
</td></tr>\
{footer_html}\
</table>\
</td></tr>\
</table>\
</body>\
</html>",
        subject_escaped = html_escape(subject),
        preheader_escaped = html_escape(preheader),
        ivory = palette::WARM_IVORY,
        teal = palette::DEEP_TEAL,
        mint = palette::MINT,
        charcoal = palette::CHARCOAL,
        hero_html = hero_html,
        body_html = body_html,
        footer_html = footer_html(footer),
    )
}

