/// Content: `AFYAMKONONI_EMAIL_CONTENT_V1.md` §1. CTA leads back to the
/// patient app (per product direction — every CTA in this module re-opens
/// the originating app/portal, never a per-record deep link).
pub fn render_patient_welcome(
    first_name: &str,
    assets: &EmailAssets,
    links: &EmailLinks,
) -> RenderedEmail {
    let name = fallback_name(first_name);
    let name_html = html_escape(name);
    let subject = "Your health journey starts with you.";
    let cta = links.patient().map(|href| Cta {
        label: "Explore AfyaMkononi",
        href,
    });
    let body_html = format!(
        "<h1 style=\"margin:0 0 16px;font-size:20px;color:{teal};\">Your health journey starts with you.</h1>\
<p style=\"margin:0 0 16px;\">Hello {name_html},</p>\
<p style=\"margin:0 0 16px;\">Welcome to <strong>AfyaMkononi</strong>! We're happy you're here.</p>\
<p style=\"margin:0 0 16px;\">Your health is personal, and getting support should feel easy, safe and free from judgment.</p>\
<p style=\"margin:0 0 16px;\">At AfyaMkononi, we believe every young person deserves the confidence to ask questions, explore their options and make informed decisions about their health.</p>\
<p style=\"margin:0 0 8px;\"><strong>Here's what you can explore:</strong></p>\
<ul style=\"margin:0 0 16px;padding-left:20px;\">\
<li style=\"margin-bottom:8px;\"><strong>Connect with care:</strong> Reach qualified healthcare professionals when you need guidance.</li>\
<li style=\"margin-bottom:8px;\"><strong>Ask freely:</strong> Find information and support in a respectful, youth-friendly space.</li>\
<li style=\"margin-bottom:8px;\"><strong>Stay informed:</strong> Explore reliable health information relevant to your life.</li>\
<li style=\"margin-bottom:8px;\"><strong>Take charge:</strong> Make healthcare decisions at your own pace, with greater confidence.</li>\
</ul>\
<p style=\"margin:0 0 16px;\">No judgment. No unnecessary barriers. Just a space designed to support your health and well-being.</p>\
<p style=\"margin:0 0 8px;font-weight:bold;\">Your Health. Your Space. Your Way.</p>\
{cta}\
<p style=\"margin:24px 0 0;\">With care,<br /><strong>The AfyaMkononi Team</strong></p>",
        teal = palette::DEEP_TEAL,
        cta = cta_button_html(cta),
    );
    let text_body = format!(
        "Your health journey starts with you.\n\n\
Hello {name},\n\n\
Welcome to AfyaMkononi! We're happy you're here.\n\n\
Your health is personal, and getting support should feel easy, safe and free from judgment.\n\n\
At AfyaMkononi, we believe every young person deserves the confidence to ask questions, explore their options and make informed decisions about their health.\n\n\
Here's what you can explore:\n\
- Connect with care: Reach qualified healthcare professionals when you need guidance.\n\
- Ask freely: Find information and support in a respectful, youth-friendly space.\n\
- Stay informed: Explore reliable health information relevant to your life.\n\
- Take charge: Make healthcare decisions at your own pace, with greater confidence.\n\n\
No judgment. No unnecessary barriers. Just a space designed to support your health and well-being.\n\n\
Your Health. Your Space. Your Way.\n\
{cta}\n\
With care,\nThe AfyaMkononi Team\n\n{footer}",
        cta = cta_text(cta),
        footer = footer_text(&Footer {
            contact_label: "Need help?",
            transactional_disclaimer: false,
        }),
    );
    RenderedEmail {
        subject: subject.to_string(),
        html_body: layout(
            subject,
            "Welcome to AfyaMkononi — your health journey starts with you.",
            Some("hero-welcome.svg"),
            "Illustration of a young person confidently using a health app",
            assets,
            &body_html,
            &Footer {
                contact_label: "Need help?",
                transactional_disclaimer: false,
            },
        ),
        text_body,
    }
}

