// =====================================================================
// 12. Password-reset verification code (Phase 2: Secure Email OTP Password
//     Recovery). Content: AFYAMKONONI_EMAIL_CONTENT_V1.md "reset mail".
//     Unlike the 11 templates above, this one IS wired to a live trigger —
//     see `password_reset_service::PasswordResetService::request_reset`,
//     sent via `email_delivery::send_rendered_otp_email_tracked` (the
//     must-propagate-failure OTP path, never the fire-and-forget
//     `send_templated_email` every other template in this module uses).
// =====================================================================

/// A prominent, monospaced display block for a numeric verification code —
/// shared by every OTP-style template in this module (the 11 transactional
/// templates above never show a bare code, so none of them needed this).
fn verification_code_block_html(code: &str) -> String {
    format!(
        "<div style=\"margin:22px 0;text-align:center;\"><div style=\"display:inline-block;padding:16px 30px;background-color:{mint};border-radius:12px;font-family:'Courier New',Courier,monospace;font-size:32px;font-weight:bold;letter-spacing:10px;color:{teal};\">{code}</div></div>",
        mint = palette::MINT,
        teal = palette::DEEP_TEAL,
        code = html_escape(code),
    )
}

fn verification_code_block_text(code: &str) -> String {
    format!("\n    {code}\n")
}

/// Content: §"reset mail". The OTP lifetime is a backend constant
/// (`password_reset_service::PASSWORD_RESET_OTP_TTL_SECONDS`, 5 minutes by
/// default) passed in as `expiry_minutes` rather than hardcoded, even though
/// the approved copy's own wording ("This code expires in **5 minutes**")
/// assumed a fixed value — so the rendered email can never drift out of
/// sync with the backend's actual expiry if that constant ever changes.
pub fn render_password_reset_otp(
    first_name: &str,
    reset_otp: &str,
    expiry_minutes: i64,
    assets: &EmailAssets,
) -> RenderedEmail {
    let name = fallback_name(first_name);
    let name_html = html_escape(name);
    let subject = "Your account. Your control.";
    let body_html = format!(
        "<h1 style=\"margin:0 0 16px;font-size:20px;color:{teal};\">Your account. Your control.</h1>\
<p style=\"margin:0 0 16px;\">Hello {name_html},</p>\
<p style=\"margin:0 0 16px;\">Need a fresh start with your password? We've got you.</p>\
<p style=\"margin:0 0 16px;\">We received a request to reset your AfyaMkononi account password.</p>\
<p style=\"margin:0 0 4px;font-weight:bold;\">Your verification code</p>\
{code_block}\
<p style=\"margin:0 0 16px;text-align:center;\">This code expires in <strong>{expiry_minutes} minutes</strong>. Enter it in the AfyaMkononi app to continue resetting your password.</p>\
<p style=\"margin:0 0 8px;\"><strong>Didn't request this?</strong></p>\
<p style=\"margin:0 0 16px;\">You can ignore this message. If you're concerned about your account, contact our support team.</p>\
<p style=\"margin:0 0 16px;\">Remember: never share your verification code with anyone, including someone claiming to represent AfyaMkononi.</p>\
<p style=\"margin:0 0 8px;font-weight:bold;\">Your Health. Your Space. Your Way.</p>\
<p style=\"margin:0;\">Stay secure,<br /><strong>The AfyaMkononi Team</strong></p>",
        teal = palette::DEEP_TEAL,
        code_block = verification_code_block_html(reset_otp),
    );
    let text_body = format!(
        "Your account. Your control.\n\n\
Hello {name},\n\n\
Need a fresh start with your password? We've got you.\n\n\
We received a request to reset your AfyaMkononi account password.\n\n\
Your verification code:\n{code_block}\n\
This code expires in {expiry_minutes} minutes. Enter it in the AfyaMkononi app to continue resetting your password.\n\n\
Didn't request this?\n\
You can ignore this message. If you're concerned about your account, contact our support team.\n\n\
Remember: never share your verification code with anyone, including someone claiming to represent AfyaMkononi.\n\n\
Your Health. Your Space. Your Way.\n\n\
Stay secure,\nThe AfyaMkononi Team\n\n{footer}",
        code_block = verification_code_block_text(reset_otp),
        footer = footer_text(&Footer {
            contact_label: "Security support:",
            transactional_disclaimer: false,
        }),
    );
    RenderedEmail {
        subject: subject.to_string(),
        html_body: layout(
            subject,
            "Use this code to reset your AfyaMkononi password.",
            Some("hero-security.svg"),
            "Shield illustration representing account security",
            assets,
            &body_html,
            &Footer {
                contact_label: "Security support:",
                transactional_disclaimer: false,
            },
        ),
        text_body,
    }
}

