    // ---------- Phase 2: password-reset OTP + dormant login-OTP templates ----------

    #[test]
    fn password_reset_otp_escapes_injection_in_first_name() {
        let r = render_password_reset_otp(SCRIPT_PAYLOAD, "482913", 5, &ASSETS_LOCAL());
        assert!(!r.html_body.contains("<script>"));
    }

    #[test]
    fn password_reset_otp_embeds_the_real_code_and_expiry() {
        let r = render_password_reset_otp("Amani", "482913", 5, &ASSETS_LOCAL());
        assert!(r.html_body.contains("482913"));
        assert!(r.text_body.contains("482913"));
        assert!(r.html_body.contains("5 minutes"));
        assert!(r.text_body.contains("5 minutes"));
    }

    #[test]
    fn password_reset_otp_never_hardcodes_the_expiry_when_given_a_different_one() {
        // Regression guard: the approved copy's own wording hardcodes "5
        // minutes", so a naive implementation could silently ignore the
        // `expiry_minutes` argument. Passing a different value must change
        // the rendered text, proving the backend-configured value actually
        // flows through rather than always rendering the literal doc text.
        let r = render_password_reset_otp("Amani", "482913", 10, &ASSETS_LOCAL());
        assert!(r.html_body.contains("10 minutes"));
        assert!(r.text_body.contains("10 minutes"));
        assert!(!r.html_body.contains("5 minutes"));
    }

