    // ---------- image-disabled readability ----------

    /// Strips every `<img ...>` tag from the rendered HTML and asserts the
    /// template's essential information is still fully present — proving no
    /// template depends on an image actually rendering.
    fn strip_img_tags(html: &str) -> String {
        let mut out = String::with_capacity(html.len());
        let mut rest = html;
        while let Some(start) = rest.find("<img") {
            out.push_str(&rest[..start]);
            let Some(end) = rest[start..].find('>') else {
                break;
            };
            rest = &rest[start + end + 1..];
        }
        out.push_str(rest);
        out
    }

    #[test]
    fn essential_content_survives_with_every_image_removed() {
        let params = ConsultationConfirmedParams {
            first_name: "Amani",
            consultation_id: "C-1001",
            appointment_date: "12 Nov 2026",
            appointment_time: "14:00",
            timezone: "EAT",
            doctor_name: "Njoroge",
        };
        let r = render_consultation_confirmed(&params, &ASSETS_LOCAL(), &links());
        let without_images = strip_img_tags(&r.html_body);
        for fact in ["Amani", "C-1001", "12 Nov 2026", "14:00", "Njoroge"] {
            assert!(
                without_images.contains(fact),
                "missing {fact} with images removed"
            );
        }
        assert!(without_images.contains("View My Consultation"));
    }

