    // ---------- backend transport integration ----------

    /// Proves these templates are actually wired to the Phase 0 backend
    /// infrastructure, not just standalone string-building functions: the
    /// rendered template is converted to a real `EmailMessage` and driven
    /// through the real `EmailTransport` trait (via `NoopEmailTransport`,
    /// never a network call) exactly as `email_delivery.rs` would. Still not
    /// a trigger — nothing calls `as_email_message` outside this test.
    #[tokio::test]
    async fn a_rendered_template_is_directly_consumable_by_the_backend_transport() {
        use crate::services::email_transport::{EmailOutcome, EmailTransport, NoopEmailTransport};

        let rendered = render_patient_welcome("Amani", &ASSETS_LOCAL(), &links());
        let message = rendered.as_email_message("patient@example.invalid");
        assert_eq!(message.subject, rendered.subject);
        assert_eq!(message.plain_text_body, rendered.text_body);
        assert_eq!(message.html_body, Some(rendered.html_body.as_str()));

        let transport = NoopEmailTransport;
        assert_eq!(
            transport.send_email(&message).await,
            EmailOutcome::NoProviderConfigured
        );
    }
